<?php	require_once('../Libraries/Functions.php');	require_once('../Libraries/Session.class.php');	require_once('../Libraries/securimage/securimage.php');	require_once('../Libraries/Connection.php');	/*Se obtienen las configuraciones*/	$GlobalConfig = array();	$Query = 'SELECT * FROM CelaConfiguraci_on';	$Result = $Connection->query($Query);	while($Record = $Result->fetch_assoc()){		$GlobalConfig[(isset($Record['Code']) && $Record['Code'] != ''? $Record['Code']:$Record['Nombre'])] = $Record['Valor'];	}	//Obtenemos la configuración para el capcha.//	$Captcha =  GetValue(//					sprintf('SELECT `Valor` FROM CelaConfiguraci_on WHERE `Nombre` = %s;',//						GetSQLValueString('Captcha', 'varchar')//					),//					'Valor'//				);	$Captcha =  $GlobalConfig['Captcha'];	if($Captcha == 1){		$SecurImage = new Securimage();		$SecurImage->use_sqlite_db  = true;//		$Length     = (int) GetValue(//								sprintf('SELECT `Valor` FROM CelaConfiguraci_on WHERE `Nombre` = %s;',//									GetSQLValueString('Tama_noCaptcha', 'varchar')//								),//								'Valor'//							);		$Length     = (int) $GlobalConfig['Tama_noCaptcha'];	}	$editFormAction = $_SERVER['PHP_SELF'];	if((isset($_POST['CelaAction'])) && ($_POST['CelaAction'] == 'Login') && $_POST['txtusuario'] != '' && $_POST['txtcontrasena'] != ''){		//Si esta incluida la libreria de captcha, se evalua.		$Success = ($Captcha == 1 ? ($SecurImage -> check($_POST['txtcaptcha'])):true);		if( $Success == false){			/*Se actualizan los intentos del usuario*/			UpdateValue('CelaUsuario', array('Intento' => '(Intento + 1)'), array('Usuario' => ' BINARY '.GetSQLValueString(trim($_POST['txtusuario']), 'varchar').''));			/*Si los intentos son tre, se bloquea el usuario*/			$Intentos = GetValue('SELECT Intento FROM CelaUsuario WHERE Usuario = BINARY '.GetSQLValueString(trim($_POST['txtusuario']), 'varchar').';', 'Intento');			if($Intentos >= 3){				UpdateValue('CelaUsuario', array('Status' => '2', 'LastLogin' => "'" . date('Y-m-d H:i:s') . "'"), array('Usuario' => ' BINARY '.GetSQLValueString(trim($_POST['txtusuario']), 'varchar')));			}			$Connection -> close();			header(sprintf('Location: %s', 'index?' . Encrypt('CaptchaFail=1&Try=' . (3 - $Intentos), 'b5s1i4t5a1316')));		}else{			$User                   = trim($_POST['txtusuario']);			$Password               = md5($_POST['txtcontrasena']);			$RedirectLoginSuccess   = 'Escritorio';			$RedirectLoginFailed    = 'index';			$LoginQuery             =   sprintf('SELECT													c.`id` as idUsuario, c.`Status` as Status, c.LastLogin, c.Intento,													c1.`id` as idRol, c1.`Siglas` as SiglasDelRol, c1.Status as StatusRol, c.Activo												 FROM CelaUsuario c													INNER JOIN CelaRol c1 ON ( c.`Rol` = c1.`id` )												 WHERE													c.`Usuario` = BINARY %s AND													c.`Contrase_na` = BINARY %s;',											GetSQLValueString($User, 'varchar'),											GetSQLValueString($Password, 'varchar')										);			$LoginResult = $Connection -> query($LoginQuery);			$LoginRecord = $LoginResult -> fetch_assoc();			if( $LoginResult -> num_rows == 1 ){ // Si existe el usuario				if($LoginRecord['Status'] == 2){					/*Se verifica el tiempo de bloqueo y los intentos*/					if(strtotime(date('Y-m-d H:i:s')) >  strtotime('+1 hour', strtotime($LoginRecord['LastLogin']))){						/*Ya ha pasado el tiempo de bloque*/						/*se verifica que hay habido intentos de inicio de sesión*/						if($LoginRecord['Intento'] > 0){							/*Si hubo intentos de inicio de sesión, se desbloquea el usuario y se reinician los intentos*/							UpdateValue('CelaUsuario', array('Status' => 1, 'LastLogin' => 'NULL', 'Intento' => 0), array('Usuario' => ' BINARY ' . GetSQLValueString($User, 'varchar') . ''));							$LoginRecord['Status'] = 1;						}					}				}				if($LoginRecord['Status'] == 1 && $LoginRecord['StatusRol'] == 1){					/*Se reinicia si es que existen intententos o ultimo inicio de sesión*/					UpdateValue('CelaUsuario', array('LastLogin' => 'NULL', 'Intento' => 0), array('Usuario' => ' BINARY ' . GetSQLValueString($User, 'varchar') . ''));//					$NombreSistema  =   GetValue(//											sprintf('SELECT `Valor` FROM CelaConfiguraci_on WHERE `Nombre` = %s;',//												GetSQLValueString('NombreSistema', 'varchar')//											),//											'Valor'//										);					$NombreSistema  =   $GlobalConfig['NombreSistema'];//					$TiempoSession  =   GetValue(//											sprintf('SELECT `Valor` FROM CelaConfiguraci_on WHERE `Nombre` = %s;',//												GetSQLValueString('TiempoDeCaducidadDeLaSesi_on(EnMinutos)', 'varchar')//											),//											'Valor'//										);					$TiempoSession  =   $GlobalConfig['TiempoDeCaducidadDeLaSesi_on(EnMinutos)'];					$Status = true;					$Random = uniqid();					setcookie('CelaRandom', $Random, time() + ($TiempoSession * 60), '/');					setcookie('idUsuario', $LoginRecord['idUsuario'], time() + ($TiempoSession * 60), '/');					$Session = new CelaSession();					$Session -> SetUser($LoginRecord['idUsuario']);					$Session -> SetCookie($Random);					$Session -> SetConnection($Connection);					$Session -> Start();					if(!$Session -> Add('CelaUser', $User)){						$Status = false;					}					if(!$Session -> Add('CelaUserId', $LoginRecord['idUsuario'])){						$Status = false;					}					if(!$Session -> Add('CelaGroup', $LoginRecord['SiglasDelRol'])){						$Status = false;					}					if(!$Session -> Add('CelaGroupId', $LoginRecord['idRol'])){						$Status = false;					}					if(!$Session -> Add('CelaAuthenticated', 'SI')){						$Status = false;					}					if(!$Session -> Add('CelaCurrentUser', -1)){						$Status = false;					}					if(!$Session -> Add('CelaCurrentMenu', '')){						$Status = false;					}					if(!$Session -> Add('CelaHostName', $NombreSistema)){						$Status = false;					}					if(!$Session -> Add('CelaFormAction', '')){						$Status = false;					}					if(!$Session -> Add('Activo', $LoginRecord['Activo'])){						$Status = false;					}					$Log =  RecordLog(								$NombreSistema,								$LoginRecord['idUsuario'],								1,								$LoginRecord['idUsuario'],								array(									'Message' => 'USER LOGIN SUCCESS',									'Data' => $_POST								)							);					if($Log['Status'] == 'OK' && $Status === true){						$Connection -> close();						header(sprintf('Location: %s', $RedirectLoginSuccess));					}else{						// Error de acceso						RecordLog(							'ACCESO A SISTEMA',							$_POST['txtusuario'],							1,							'',							array(								'Message' => 'USER NOT FOUND',								'Data' => $_POST							)						);						//DestroySession();						$Session -> Destroy();						$Connection -> close();						header(sprintf('Location: %s', 'index?' . Encrypt('LogFail=1', 'b5s1i4t5a1316')));					}				}else{					// EL usuario esta bloqueado o cancelado					RecordLog(						'ACCESO A SISTEMA',						$_POST['txtusuario'],						$LoginRecord['idUsuario'],						'',						array(							'Message' => 'UNAUTHORIZED USER',							'Data' => $_POST						)					);					DestroySession();					$Connection -> close();					header(sprintf('Location: %s', 'index?' . Encrypt('UserLock=1', 'b5s1i4t5a1316')));				}			}else{				RecordLog(					'ACCESO A SISTEMA',					$_POST['txtusuario'],					'',					'',					array(						'Message' => 'RESTRICTED ACCESS, POSSIBLE ROBOT',						'Data' => $_POST					)				);				/*Se actualizan los intentos del usuario*/				UpdateValue('CelaUsuario', array('Intento' => '(Intento + 1)'), array('Usuario' => ' BINARY '.GetSQLValueString(trim($_POST['txtusuario']), 'varchar').''));				/*Si los intentos son tre, se bloquea el usuario*/				$Intentos = GetValue('SELECT Intento FROM CelaUsuario WHERE Usuario = BINARY '.GetSQLValueString(trim($_POST['txtusuario']), 'varchar').';', 'Intento');				if($Intentos >= 3){					UpdateValue('CelaUsuario', array('Status' => '2', 'LastLogin' => "'" . date('Y-m-d H:i:s') . "'"), array('Usuario' => ' BINARY '.GetSQLValueString(trim($_POST['txtusuario']), 'varchar')));				}				DestroySession();				$Connection -> close();				header(sprintf('Location: %s', 'index?' . Encrypt('LoginFail=1&Try=' . (3 - $Intentos), 'b5s1i4t5a1316')));			}		}	}?>